import{_ as i,o as t,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-12-11","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-12-11","date":"2024-12-11T00:00:00.000Z","updated":"2024-12-11T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","元数据同步","多区域复制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-12-11.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-12-11.md","lastUpdated":1780459816000}'),n={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-12-11.md"};function r(a,l,s,u,p,c){return t(),o("div",null,[...l[0]||(l[0]=[e('<p>会议纪要</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>Ceph RGW 多区域（Multisite）和元数据同步讨论</p><h3 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h3><p>Cena, Casey, Yehuda 等</p><h3 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h3><p>未知</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>多区域（Multisite）复制策略的讨论</strong></p><ul><li><strong>当前问题</strong>：多区域复制（Multisite Replication）在实现上存在一些混淆，特别是在对称复制（symmetric replication）和增量复制（incremental sync）之间的选择。</li><li><strong>讨论内容</strong>： <ul><li>当前实现要求两个桶（bucket）完全一致，但有些用户希望使用复制作为数据流动，而不是确保两个桶完全相同。</li><li>新的多区域组（Multisite Group）实现允许根据同步策略（sync policy）选择性地复制对象，而不是强制全量同步。</li><li>AWS 的桶复制策略（bucket replication policy）不支持全量同步，只对新上传的对象进行复制。</li></ul></li><li><strong>决定</strong>： <ul><li>需要进一步讨论是否支持全量同步和增量同步的混合模式，以及如何在多区域组（Multisite Group）和多区域（Multisite）之间进行选择。</li><li>需要明确多区域组（Multisite Group）和多区域（Multisite）的使用场景，特别是灾难恢复（Disaster Recovery）的需求。</li></ul></li></ul></li><li><p><strong>元数据同步（Metadata Sync）的优化</strong></p><ul><li><strong>当前问题</strong>：元数据同步在多区域组（Multisite Group）中存在不必要的负载，特别是当其他区域组（Zone Group）并不关心某些桶的元数据时。</li><li><strong>讨论内容</strong>： <ul><li>当前实现会将所有桶的元数据复制到所有区域组，这可能导致不必要的负载和竞争条件。</li><li>建议优化元数据同步，只同步相关区域组（Zone Group）的元数据。</li></ul></li><li><strong>决定</strong>： <ul><li>需要进一步讨论如何在元数据同步中避免不必要的负载，特别是在区域组（Zone Group）之间的同步。</li></ul></li></ul></li><li><p><strong>同步策略（Sync Policy）与全局同步（Global Sync）的冲突</strong></p><ul><li><strong>当前问题</strong>：同步策略（Sync Policy）允许在同一区域组（Zone Group）内进行不对称同步，这可能导致数据不一致。</li><li><strong>讨论内容</strong>： <ul><li>同步策略（Sync Policy）允许用户在同一区域组内进行不对称同步，但这与全局同步（Global Sync）的目标相冲突。</li><li>建议在区域组（Zone Group）级别进行全局同步，而桶级别的同步策略（bucket replication policy）应仅用于跨区域组（Zone Group）的同步。</li></ul></li><li><strong>决定</strong>： <ul><li>需要进一步讨论是否应该禁用同步策略（Sync Policy）中的不对称同步，以确保区域组（Zone Group）内的数据一致性。</li></ul></li></ul></li><li><p><strong>桶索引清理（Bucket Index Cleanup）的讨论</strong></p><ul><li><strong>当前问题</strong>：桶索引清理的实现需要考虑不同区域组（Zone Group）之间的同步状态。</li><li><strong>讨论内容</strong>： <ul><li>当前实现只考虑同一区域组（Zone Group）内的同步状态，未考虑跨区域组的同步。</li><li>建议在清理桶索引时，确保所有相关区域组（Zone Group）都已完成同步。</li></ul></li><li><strong>决定</strong>： <ul><li>需要进一步讨论如何在跨区域组（Zone Group）的情况下进行桶索引清理，并确保数据一致性。</li></ul></li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>多区域（Multisite）复制策略的进一步讨论</strong>：</p><ul><li>需要撰写设计文档，明确全量同步和增量同步的混合模式，以及多区域组（Multisite Group）和多区域（Multisite）的使用场景。</li><li>讨论是否支持多区域组（Multisite Group）内的不对称同步。</li></ul></li><li><p><strong>元数据同步的优化</strong>：</p><ul><li>进一步讨论如何在元数据同步中避免不必要的负载，特别是在区域组（Zone Group）之间的同步。</li></ul></li><li><p><strong>同步策略（Sync Policy）与全局同步（Global Sync）的冲突</strong>：</p><ul><li>讨论是否禁用同步策略（Sync Policy）中的不对称同步，以确保区域组（Zone Group）内的数据一致性。</li></ul></li><li><p><strong>桶索引清理的进一步讨论</strong>：</p><ul><li>讨论如何在跨区域组（Zone Group）的情况下进行桶索引清理，并确保数据一致性。</li></ul></li></ol><p><strong>下次会议时间</strong>：待定</p>',12)])])}const h=i(n,[["render",r]]);export{_ as __pageData,h as default};
